const listTournaments = `-- name: ListTournaments :many
SELECT id, complex_id, name, sport, start_date, end_date, status, cancel_reason, cancelled_at, cancelled_by, created_by, created_at, updated_at FROM tournaments
WHERE complex_id = $1
  AND end_date >= $2::date
  AND start_date <= $3::date
  AND ($4::bool OR status = 'active')
ORDER BY start_date, id
LIMIT $5::int
`

type ListTournamentsParams struct {
	ComplexID        pgtype.UUID `json:"complex_id"`
	DateFrom         pgtype.Date `json:"date_from"`
	DateTo           pgtype.Date `json:"date_to"`
	IncludeCancelled bool        `json:"include_cancelled"`
	PageLimit        int32       `json:"page_limit"`
}

// The tournaments of one complex that overlap the window, soonest first.
// include_cancelled is what the owner's list sets and the public one does not.
func (q *Queries) ListTournaments(ctx context.Context, arg ListTournamentsParams) ([]Tournament, error) {
	rows, err := q.db.Query(ctx, listTournaments,
		arg.ComplexID,
		arg.DateFrom,
		arg.DateTo,
		arg.IncludeCancelled,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Tournament
	for rows.Next() {
		var i Tournament
		if err := rows.Scan(
			&i.ID,
			&i.ComplexID,
			&i.Name,
			&i.Sport,
			&i.StartDate,
			&i.EndDate,
			&i.Status,
			&i.CancelReason,
			&i.CancelledAt,
			&i.CancelledBy,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockTournament = `-- name: LockTournament :one
SELECT id, complex_id, name, sport, start_date, end_date, status, cancel_reason, cancelled_at, cancelled_by, created_by, created_at, updated_at FROM tournaments WHERE id = $1 FOR UPDATE
`

// Cancelling a tournament and creating or changing its categories take this
// lock first, so they cannot interleave.
func (q *Queries) LockTournament(ctx context.Context, id pgtype.UUID) (Tournament, error) {
	row := q.db.QueryRow(ctx, lockTournament, id)
	var i Tournament
	err := row.Scan(
		&i.ID,
		&i.ComplexID,
		&i.Name,
		&i.Sport,
		&i.StartDate,
		&i.EndDate,
		&i.Status,
		&i.CancelReason,
		&i.CancelledAt,
		&i.CancelledBy,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

