const setMatchResult = `-- name: SetMatchResult :exec
UPDATE tournament_matches
SET status = 'completed', winner_pair_id = $2, sets = $4::text::jsonb, walkover_loser = $3, completed_at = NOW()
WHERE id = $1
`

type SetMatchResultParams struct {
	ID            pgtype.UUID `json:"id"`
	WinnerPairID  pgtype.UUID `json:"winner_pair_id"`
	WalkoverLoser pgtype.Int4 `json:"walkover_loser"`
	Sets          pgtype.Text `json:"sets"`
}

// sets travels as text with an explicit cast: the pool's exec mode would send a
// []byte as bytea, which Postgres refuses to read as json (see audit.Insert).
func (q *Queries) SetMatchResult(ctx context.Context, arg SetMatchResultParams) error {
	_, err := q.db.Exec(ctx, setMatchResult,
		arg.ID,
		arg.WinnerPairID,
		arg.WalkoverLoser,
		arg.Sets,
	)
	return err
}

const setMatchSlot = `-- name: SetMatchSlot :exec
UPDATE tournament_matches
SET pair1_id = CASE WHEN $1::int = 1 THEN $2::uuid ELSE pair1_id END,
    pair2_id = CASE WHEN $1::int = 2 THEN $2::uuid ELSE pair2_id END
WHERE id = $3
`

type SetMatchSlotParams struct {
	Slot   int32       `json:"slot"`
	PairID pgtype.UUID `json:"pair_id"`
	ID     pgtype.UUID `json:"id"`
}

// Puts a pair in one of a match's two slots (1 or 2), or empties it.
func (q *Queries) SetMatchSlot(ctx context.Context, arg SetMatchSlotParams) error {
	_, err := q.db.Exec(ctx, setMatchSlot, arg.Slot, arg.PairID, arg.ID)
	return err
}

